// Project-adapted summoner configuration. Unverified distances and auxiliary timings are engineering defaults.
(()=>{'use strict';
const config=window.SUMMONER_CONFIG={
 flash:{name:'闪现',icon:'闪',cd:150,target:'direction',range:200,reference:'project-default-distance'},
 teleport:{name:'传送',icon:'传',cd:150,target:'ally',channel:3.5,buildingOnlyBefore:0,restrictedRadius:900},
 cleanse:{name:'净化',icon:'净',cd:110,target:'self',immunity:.25},
 heal:{name:'治疗',icon:'疗',cd:100,target:'self',range:850,min:110,max:400,speed:.3,duration:2,repeatWindow:35},
 barrier:{name:'屏障',icon:'障',cd:100,target:'self',min:120,max:560,duration:2.5},
 exhaust:{name:'虚弱',icon:'虚',cd:100,target:'enemy',range:650,slow:.35,reduction:.4,duration:2.5},
 ignite:{name:'点燃',icon:'燃',cd:100,target:'enemy',range:600,min:72,max:380,duration:5,grievous:.6},
 ghost:{name:'疾跑',icon:'疾',cd:90,target:'self',speed:.6,finalSpeed:.25,duration:8,extension:6},
 smite:{name:'惩戒',icon:'惩',cd:10,target:'smite',range:600,recharge:45,maxCharges:2,damage:[600,1000,1400],thresholds:[8,20],monsterDamageReduction:.5,jungleHealPct:.02}
};
window.createSummonerSpells=function(env,m){
 const core=m.core,now=env.time,units=env.units,alive=u=>u&&u.hp>0&&!(u.death>0),distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),scaled=(u,a,b)=>a+(b-a)*Math.max(0,Math.min(17,(u.level||1)-1))/17;
 const whitelist=new Set(['STUN','ROOT','SILENCE','SLOW']);
 const lookup=id=>units().find(u=>u.id===id);
 function init(u,ids=['flash','heal']){let chosen=Array.isArray(ids)?ids:[];if(chosen.length!==2||chosen[0]===chosen[1]||chosen.some(id=>!config[id]))return false;u.summoners=chosen.slice();u.summonerCooldowns??={};u.summonerState??={cooldownEnds:{},smite:{charges:2,nextCharge:0,lastUse:-Infinity,ecology:0}};u.summonerState.cooldownEnds??={};u.summonerState.smite??={charges:2,nextCharge:0,lastUse:-Infinity,ecology:0};return true}
 function ensure(u){if(!u.summonerState)init(u,u.summoners||['flash','heal']);return u.summonerState}
 function emit(u,id,target,event){core.emit('AbilityCommitted',u,target,{abilityId:'summoner:'+id,castId:event.castId});env.ring?.(u.x,u.y,50,'#ecd89e',.3)}
 function deny(u,text){if(u.player)env.toast?.(text);return false}
 function cooldown(u,id){let s=ensure(u);if(id==='smite'){let q=s.smite;return Math.max(0,q.charges>0?10-(now()-q.lastUse):q.nextCharge-now())}return Math.max(0,(s.cooldownEnds[id]||0)-now())}
 function cancel(u,reason='cancelled'){let c=u.summonerChannel;if(!c)return false;delete u.summonerChannel;core.emit('AbilityInterrupted',u,c.target,{abilityId:'summoner:teleport',castId:c.event.castId,reason});return true}
 function restricted(u,target){if(env.teleportRestricted)return env.teleportRestricted(u,target);return units().some(v=>v.type==='nexus'&&v.team!==u.team&&distance(v,target)<config.teleport.restrictedRadius)}
 const smallMonster=t=>t?.type==='monster'&&['MURK_WOLF','RAPTOR','KRUG','MINI_KRUG','VOIDMITE'].includes(t.monsterId);
 function cast(u,slotOrId,point={}){
  if(!alive(u)||env.state&&env.state()!=='playing')return false;let state=ensure(u),id=typeof slotOrId==='number'?u.summoners[slotOrId]:slotOrId,s=config[id];if(!s||!u.summoners.includes(id))return false;
  if(u.hero==='zero'&&u.invisible>0)return false;if((u.yasuoUltLockUntil||0)>now())return deny(u,'当前状态无法释放');if(id!=='cleanse'&&(core.hardLocked(u)||u.silence>0||u.untargetable>0))return deny(u,'当前状态无法释放');if(id==='cleanse'&&(u.suppression>0||u.airborne>0))return false;
  if(cooldown(u,id)>1e-9)return deny(u,'召唤师技能冷却中');let target=point?.target||(point?.type?point:null);
  if(id==='smite'&&(!alive(target)||smallMonster(target))){let big=units().filter(v=>alive(v)&&v.type==='monster'&&!smallMonster(v)&&v.team!==u.team&&!(v.untargetable>0)&&distance(u,v)<=s.range+(v.radius||0)).sort((a,b)=>distance(u,a)-distance(u,b))[0];if(big)target=big;else if(target&&smallMonster(target)){u.smiteSilent=true;return false}}
  if(s.target==='enemy'||s.target==='smite'){if(!alive(target)||target.team===u.team||distance(u,target)>s.range||target.untargetable>0||env.canTarget&&!env.canTarget(u,target))return deny(u,'请选择范围内的敌方目标');if(s.target==='enemy'&&target.type!=='hero')return false;if(id==='smite'&&!['minion','monster','hero'].includes(target.type))return false;if(id==='smite'&&target.type==='hero'&&state.smite.ecology<8)return deny(u,'惩戒尚未进化，无法对英雄使用');if(id==='smite'&&smallMonster(target))return false}
  if(id==='teleport'){if(!alive(target)||target===u||target.team!==u.team||!['hero','minion','monster','tower','nexus','ward','inhibitor'].includes(target.type)||restricted(u,target))return deny(u,'请选择合法友方传送目标');if(now()<s.buildingOnlyBefore&&!['tower','nexus','inhibitor'].includes(target.type))return deny(u,'前6分钟只能传送到友方建筑');if(u.root>0)return false}
  if(id==='flash'&&u.root>0&&!core.onlyGravityRoot?.(u))return false;
  if(u.summonerChannel)cancel(u,'another-summoner');let e=core.instance(u,'summoner:'+id);core.emit('AbilityCastStarted',u,target||u,{abilityId:'summoner:'+id,castId:e.castId});
  if(id==='flash'){let dx=point.x-u.x,dy=point.y-u.y;if(!Number.isFinite(dx)||!Number.isFinite(dy)||Math.hypot(dx,dy)<1){dx=Math.cos(u.angle||0);dy=Math.sin(u.angle||0)}let length=Math.hypot(dx,dy),step=Math.min(s.range,length>1?length:s.range),end={x:u.x+dx/length*step,y:u.y+dy/length*step};m.cancelAttack?.(u);if(!core.startDisplacement(u,end,{type:'BLINK',abilityId:'summoner:flash'}))return false;m.runeEffects?.onDisplace?.(u,'flash');env.ring?.(u.x,u.y,75,'#fff1a6',.35)}
  if(id==='teleport'){u.summonerChannel={target,event:e,started:now(),ends:now()+s.channel,x:u.x,y:u.y};m.cancelAttack?.(u);env.areaWarning?.(target,110,s.channel,'#9edbff');env.line?.(u,target,'#9edbff',4,s.channel)}
  if(id==='cleanse'){core.remove(u,v=>(whitelist.has(v.type)&&!['permanent','suppression','airborne'].includes(v.dispelCategory))||v.tag==='SUMMONER_IGNITE','cleansed');for(let k of ['stun','root','silence','slow'])if(!core.statuses(u,k).length)u[k]=0;core.apply(u,'CLEANSE_IMMUNITY',s.immunity,u,{tenacity:false,dispelCategory:'buff'});core.sync(u)}
  if(id==='heal'){let ally=units().filter(v=>v!==u&&v.type==='hero'&&v.team===u.team&&alive(v)&&distance(u,v)<=s.range).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp||a.hp-b.hp||a.id-b.id)[0];for(let v of [u,ally].filter(Boolean)){let penalty=(v.summonerHealUntil||0)>now()?.5:1;m.heal(v,scaled(u,s.min,s.max)*penalty,u,{event:e,abilityId:'summoner:heal'});v.summonerHealUntil=now()+s.repeatWindow;core.apply(v,'MOVE_SPEED_BUFF',s.duration,u,{amount:s.speed,tenacity:false,uniqueKey:'summoner-heal:'+u.id})}}
  if(id==='barrier')m.shield(u,scaled(u,s.min,s.max),s.duration,u,{event:e});
  if(id==='exhaust'){core.apply(target,'SUMMONER_EXHAUST',s.duration,u,{amount:s.reduction,abilityId:'summoner:exhaust',tenacity:false});m.slow(target,s.slow,s.duration,u,{to:0,duration:s.duration},'summoner-exhaust:'+u.id)}
  if(id==='ignite'){let key='ignite:'+u.id;core.apply(target,'IGNITE',s.duration+.001,u,{uniqueKey:key,tag:'SUMMONER_IGNITE',abilityId:'summoner:ignite',tenacity:false});core.apply(target,'HEAL_REDUCTION',s.duration,u,{amount:s.grievous,uniqueKey:key+':heal',tag:'SUMMONER_IGNITE',abilityId:'summoner:ignite',tenacity:false});target.summonerDots??=[];target.summonerDots=target.summonerDots.filter(v=>v.key!==key);target.summonerDots.push({key,kind:'ignite',source:u,event:e,next:now()+.25,remaining:20,step:.25,damage:scaled(u,s.min,s.max)/20})}
  if(id==='ghost'){state.ghost={ends:now()+s.duration,refreshed:now()};applyGhost(u)}
  if(id==='smite'){let q=state.smite,stage=q.ecology>=20?2:q.ecology>=8?1:0;q.charges--;q.lastUse=now();if(!q.nextCharge)q.nextCharge=now()+s.recharge;if(target.type==='hero'){m.deal(target,40,u,'true',{event:e,once:true});m.slow(target,.25,2,u,null,'smite:'+u.id);core.apply(u,'MOVE_SPEED_BUFF',2,u,{amount:.25,tenacity:false,uniqueKey:'smite-steal'})}else m.deal(target,s.damage[stage],u,'true',{event:e,once:true})}
  let duration=s.cd/(1+((m.runeEffects?.summonerHaste?.(u)||0)+(m.itemEffects?.summonerHaste?.(u)||0)+(window.GameModes?.isARAM()?GAME_CONFIG.aram.summoner_haste:0))/100);state.cooldownEnds[id]=now()+duration;u.summonerCooldowns[id]=duration;m.runeEffects?.onCast?.(u,'summoner:'+id,e);emit(u,id,target||u,e);return true;
 }
 function applyGhost(u){let g=u.summonerState.ghost,s=config.ghost,amount=s.speed+(s.finalSpeed-s.speed)*Math.min(1,(now()-g.refreshed)/s.duration);core.apply(u,'MOVE_SPEED_BUFF',Math.max(.01,g.ends-now()),u,{amount,tenacity:false,refresh:true,uniqueKey:'summoner-ghost'})}
 function tick(u,dt){if(m.temporal?.isFrozen(u))return;let s=ensure(u);let hot=u.smiteHot;if(hot){while(alive(u)&&hot.next<=now()+1e-9&&hot.next<=hot.until+1e-9){m.heal(u,hot.amount,u,{abilityId:'summoner:smite'});hot.next+=.1}if(now()>=hot.until||!alive(u))u.smiteHot=null}for(let id of u.summoners)u.summonerCooldowns[id]=cooldown(u,id);let q=s.smite;if(q.charges<2&&q.nextCharge>0){while(q.charges<2&&q.nextCharge<=now()+1e-9){q.charges++;q.nextCharge=q.charges<2?q.nextCharge+config.smite.recharge:0}u.summonerCooldowns.smite=cooldown(u,'smite')}
  if(s.ghost){if(!alive(u)||now()>=s.ghost.ends){core.remove(u,v=>v.uniqueKey==='summoner-ghost','expired');delete s.ghost}else applyGhost(u)}
  if(u.summonerChannel){let c=u.summonerChannel;if(!alive(u)||!alive(c.target)||core.hardLocked(u)||u.silence>0||distance(u,c)>2||restricted(u,c.target)){cancel(u,'channel-interrupted')}else if(now()+1e-9>=c.ends){let end=core.safePoint(u,c.target,u.radius||22,{crossWalls:true});u.x=end.x;u.y=end.y;core.spatial.update(u);delete u.summonerChannel;m.runeEffects?.onDisplace?.(u,'teleport');core.emit('SummonerTeleportCompleted',u,c.target,{castId:c.event.castId});env.ring?.(u.x,u.y,120,'#9edbff',.5)}}
  if(u.summoners.includes('smite')&&q.ecology>=20&&env.inJungle?.(u))core.apply(u,'MOVE_SPEED_BUFF',.15,u,{amount:now()-(u.lastHit??-99)<5?.05:.1,tenacity:false,refresh:true,uniqueKey:'smite-jungle'});
 }
 function addEcology(u,count=1){let q=ensure(u).smite;if(!u.summoners.includes('smite')||!Number.isFinite(count)||count<=0)return q.ecology;let before=q.ecology;q.ecology+=Math.floor(count);if((before<8&&q.ecology>=8)||(before<20&&q.ecology>=20))core.emit('SummonerSmiteEvolved',u,u,{ecology:q.ecology,damage:config.smite.damage[q.ecology>=20?2:1]});return q.ecology}
 function tickWorld(){for(let t of units()){if(m.temporal?.isFrozen(t))continue;if(!t.summonerDots?.length)continue;for(let dot of t.summonerDots){if(m.temporal?.isFrozen(dot.source)){m.temporal.shift(dot,1/60);continue}if(!alive(t)){dot.remaining=0;continue}if(dot.kind==='ignite'&&!core.statuses(t,'IGNITE').some(v=>v.uniqueKey===dot.key)){dot.remaining=0;continue}while(dot.remaining>0&&dot.next<=now()+1e-9){m.deal(t,dot.damage,dot.source,'true',{event:dot.event,once:true,hitIndex:dot.key+':'+dot.remaining});dot.remaining--;dot.next+=dot.step||1;}}t.summonerDots=t.summonerDots.filter(v=>v.remaining>0)}}
 function reveal(team,t){return core.statuses(t,'IGNITE').some(v=>v.source?.team===team)}
 core.on('UnitKilled',e=>{let dead=lookup(e.targetId);if(!dead||dead._summonerRewardedLife===(dead._life||0))return;dead._summonerRewardedLife=dead._life||0;if(dead.type==='hero'){for(let u of units()){let participated=e.sourceId===u.id||dead.attackers?.[u.id]!=null&&now()-dead.attackers[u.id]<=10;if(alive(u)&&u.team!==dead.team&&participated&&u.summonerState?.ghost){u.summonerState.ghost.ends+=config.ghost.extension;u.summonerState.ghost.refreshed=now();applyGhost(u)}}}else if(dead?.type==='monster'){let owner=lookup(e.sourceId);if(owner?.summoners?.includes('smite'))addEcology(owner,dead.ecologyReward||1)}});
 core.on('DamageApplied',e=>{let u=lookup(e.sourceId),t=lookup(e.targetId);if(!u?.summoners?.includes('smite')||t?.type!=='monster'||!alive(t)||e.abilityId==='summoner:smite-burn'||e.abilityId==='summoner:smite')return;let damage=scaled(u,22,162)+.1*Math.max(0,(u.attack||0)-(u.baseAttack||0))+.12*(u.ap||0)+.25*(u.bonusArmor||0)+.25*(u.bonusMr||0)+.04*(u.bonusHp||0),key='jungle:'+u.id;t.summonerDots??=[];let existing=t.summonerDots.find(v=>v.key===key);if(existing){existing.remaining=12;existing.damage=damage/4}else t.summonerDots.push({key,kind:'jungle',source:u,event:core.instance(u,'summoner:smite-burn'),next:now()+.25,step:.25,remaining:12,damage:damage/4});u.smiteHot={until:now()+3,next:now()+.1,amount:u.maxHp*config.smite.jungleHealPct*3/30}});
 function describe(u,slot){let id=typeof slot==='number'?u.summoners?.[slot]:slot,s=config[id];if(!s)return '';let text=s.name+' · 冷却 '+Math.ceil(cooldown(u,id))+' / '+s.cd+' 秒';if(id==='smite'){let q=ensure(u).smite;text+=' · '+q.charges+'/2 充能 · 生态 '+q.ecology+' · '+s.damage[q.ecology>=20?2:q.ecology>=8?1:0]+' 真实伤害'}if(id==='flash')text+=' · 距离 '+s.range+'（项目适配）';return text}
 return{config,init,cast,tick,tickWorld,reveal,addEcology,cancel,cooldown,describe,outgoingMultiplier:u=>1-Math.max(0,...core.statuses(u,'SUMMONER_EXHAUST').map(v=>v.amount||0)),incomingMonsterMultiplier:(u,t)=>u.summoners?.includes('smite')&&t?.type==='monster'&&!t.epic ? .5 : 1};
};
})();
